import { getRequestConfig } from 'next-intl/server';

import { resolveLocale, TIME_ZONE } from './routing';

/**
 * Referenced by `next.config.ts` via `createNextIntlPlugin('./src/core/i18n/request.ts')`.
 * `messages/{az,ru,en}.json` are generated by `scripts/i18n-merge.mjs` — never hand-edited.
 */
export default getRequestConfig(async ({ requestLocale }) => {
  // An unknown `[locale]` segment (e.g. `/unknown.txt`) falls back to az.
  const locale = resolveLocale(await requestLocale);

  const messages = (await import(`../../../messages/${locale}.json`)).default;

  return {
    locale,
    messages,
    timeZone: TIME_ZONE,
    // A missing key must never blank out a screen: render the key path instead.
    getMessageFallback: ({ key, namespace }) => (namespace ? `${namespace}.${key}` : key),
    onError: () => {
      // Swallowed on purpose: `i18n:check` is the gate for missing/broken keys,
      // and a runtime warning per render would flood the logs.
    },
  };
});
